// Mismo mapa que en el workflow de cotización: manténgalos sincronizados, o reemplace los dos
// por un nodo de credencial/lookup compartido (p. ej. un Google Sheet) si va a usar varios números.
const TELEFONO_A_CHAT_ID = {
  '3009998877': 123456789, // Marta Gil (ejemplo del Instructivo 5) -> reemplazar
};
const datos = items[0].json.body ?? items[0].json;
const chat_id = TELEFONO_A_CHAT_ID[datos.cliente.telefono];
if (!chat_id) throw new Error(`Sin chat_id para el teléfono ${datos.cliente.telefono}: agréguelo al mapa del nodo de Código.`);
return [{ json: { ...datos, chat_id } }];
